
from pathlib import Path

import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns


# Define project paths
BASE_DIR = Path(__file__).resolve().parent
RESULTS_DIR = BASE_DIR / "results"

RACE_FILE = RESULTS_DIR / "female_mortality_by_race_2023_2025.csv"
SUMMARY_FILE = RESULTS_DIR / "female_mortality_summary_2023_2025.csv"

# Configure the chart style
sns.set_theme(style="whitegrid", palette="deep")

# Create the output directory if needed
RESULTS_DIR.mkdir(parents=True, exist_ok=True)


def load_results():
    """Load the CSV files generated by app.py."""

    race_df = pd.read_csv(RACE_FILE)
    summary_df = pd.read_csv(SUMMARY_FILE)

    return race_df, summary_df


def create_race_distribution_chart(race_df):
    """Compare the percentage distribution by race/color."""

    chart_df = race_df[
        race_df["Race"].isin(
            [
                "White",
                "Black (Preta)",
                "Brown (Parda)",
                "Asian (Amarela)",
                "Indigenous",
            ]
        )
    ].copy()

    plt.figure(figsize=(12, 6))

    sns.barplot(
        data=chart_df,
        x="Race",
        y="Percentage",
        hue="Year",
        errorbar=None,
    )

    plt.title(
        "Distribution of Female Deaths by Race/Color",
        fontsize=15,
        pad=15,
    )
    plt.xlabel("Race/Color")
    plt.ylabel("Percentage of Female Deaths")
    plt.xticks(rotation=15, ha="right")
    plt.legend(title="Year")
    plt.tight_layout()

    output_path = RESULTS_DIR / "race_distribution.png"
    plt.savefig(output_path, dpi=300, bbox_inches="tight")
    plt.close()

    print(f"Saved: {output_path}")


def create_black_women_chart(summary_df):
    """Compare recorded deaths among Black women."""

    plt.figure(figsize=(8, 6))

    ax = sns.barplot(
        data=summary_df,
        x="Year",
        y="BlackWomenDeaths",
        hue="Year",
        legend=False,
        errorbar=None,
    )

    ax.bar_label(ax.containers[0], fmt="%.0f", padding=3)

    plt.title(
        "Recorded Deaths Among Black Women",
        fontsize=15,
        pad=15,
    )
    plt.xlabel("Year")
    plt.ylabel("Number of Deaths")
    plt.tight_layout()

    output_path = RESULTS_DIR / "black_women_deaths.png"
    plt.savefig(output_path, dpi=300, bbox_inches="tight")
    plt.close()

    print(f"Saved: {output_path}")


def create_black_women_percentage_chart(summary_df):
    """Compare Black women's share of female deaths."""

    plt.figure(figsize=(8, 6))

    ax = sns.barplot(
        data=summary_df,
        x="Year",
        y="BlackWomenPercentage",
        hue="Year",
        legend=False,
        errorbar=None,
    )

    ax.bar_label(
        ax.containers[0],
        fmt="%.2f%%",
        padding=3,
    )

    plt.title(
        "Black Women's Share of Female Deaths",
        fontsize=15,
        pad=15,
    )
    plt.xlabel("Year")
    plt.ylabel("Percentage (%)")
    plt.tight_layout()

    output_path = RESULTS_DIR / "black_women_percentage.png"
    plt.savefig(output_path, dpi=300, bbox_inches="tight")
    plt.close()

    print(f"Saved: {output_path}")


def main():
    """Generate all charts."""

    race_df, summary_df = load_results()

    create_race_distribution_chart(race_df)
    create_black_women_chart(summary_df)
    create_black_women_percentage_chart(summary_df)

    print("\nAll charts were generated successfully.")


if __name__ == "__main__":
    main()